{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "resolution_minutes",
  "per_column": [
    {
      "name": "issue_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Categorizes the nature of the issue (bug, outage, feature request, etc.), derivable from the issue_description at ticket intake and knowable before resolution. Different issue types plausibly carry strong signal about resolution time without restating or leaking it."
    },
    {
      "name": "blocker_scope",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Scope of who is blocked (single user vs. all tenants) is an intake-time attribute independent of resolution duration. It plausibly correlates with escalation and complexity, offering legitimate predictive signal."
    },
    {
      "name": "business_impact",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Severity of business impact (friction vs. financial/compliance risk) is assessable at ticket creation from the description and is not a component or deterministic function of resolution_minutes. It plausibly predicts prioritization and handling time."
    },
    {
      "name": "root_cause_clarity",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "How well the root cause is characterized at submission (evidence provided vs. requires investigation) is an early-stage feature independent of the outcome. Greater initial clarity plausibly shortens resolution, giving genuine predictive leverage."
    }
  ],
  "n_predictors": 4,
  "predictive_utility": 0.75,
  "rationale": "All four added columns are intake-time, description-derived attributes that lie outside the focus variable: none restates, componentizes, or leaks resolution_minutes, and none is knowable only post-outcome. Each plausibly carries distinct predictive signal (issue nature, blast radius, impact severity, diagnostic clarity) beyond the original priority/channel/agent columns, and together they span complementary dimensions of ticket complexity. Utility is strong but not maximal because some overlap with existing 'priority' is likely and the signals are heuristic categorizations rather than harder quantitative predictors."
}

